def solve(inp):
    from collections import Counter
    vals=Counter(c for r in inp for c in r)
    bg=vals.most_common(1)[0][0]
    H,W=len(inp),len(inp[0])
    linesr=[r for r,rw in enumerate(inp) if len(set(rw))==1 and rw[0]!=bg]
    linesc=[c for c in range(W) if len({inp[i][c] for i in range(H)})==1 and inp[0][c]!=bg]
    lc=inp[linesr[0]][0]
    obj={(i,j) for i in range(H) for j in range(W) if inp[i][j]==lc and (i not in linesr or j not in linesc)}
    rmr=[i for i in range(H) if i not in linesr]; rmap=dict(zip(rmr,list(range(len(rmr)))))
    rcm=[j for j in range(W) if j not in linesc]; cmap=dict(zip(rcm,list(range(len(rcm)))))
    oh,ow=len(rmr),len(rcm)
    out=[[bg]*ow for _ in range(oh)]
    for i,j in obj:
        ri=rmap[i]; rc=cmap[j]
        for di in (-1,0,1):
            for dj in (-1,0,1):
                ni,nj=ri+di,rc+dj
                if 0<=ni<oh and 0<=nj<ow:
                    out[ni][nj]=lc
    return out
